function pseudo(text) {
  const map = { a: 'à', e: 'é', i: 'î', o: 'ö', u: 'ü' };
  let out = '';
  let inPlaceholder = false;
  for (const ch of text) {
    if (ch === '{') inPlaceholder = true;
    if (ch === '}') inPlaceholder = false;
    out += !inPlaceholder && map[ch] ? map[ch] : ch;
  }
  return '[' + out + ' ' + '~'.repeat(Math.ceil(text.length * 0.3)) + ']';
}

